using System;using System.Data;using System.Data.SqlClient;using System.IO;
namespace Training.Manager{public partial class Notifications:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string Sender{get{return "MANAGER:"+Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(Session["ManagerID"]==null)Response.Redirect("~/Default.aspx");if(!IsPostBack)BindGrid();}protected void btnSend_Click(object s,EventArgs e){if(string.IsNullOrWhiteSpace(txtMessage.Text)){lblMessage.Text="Notification is required.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}string id=Guid.NewGuid().ToString("N").Substring(0,12).ToUpper();string path=Server.MapPath("~/Uploads/Notifications/");if(!Directory.Exists(path))Directory.CreateDirectory(path);if(fuPdf.HasFile){string ext=Path.GetExtension(fuPdf.FileName).ToLower();if(ext!=".pdf"){lblMessage.Text="Only PDF file is allowed.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}fuPdf.SaveAs(Path.Combine(path,id+".pdf"));}obj.ExecuteSql("INSERT INTO Notification(NotificationID,TrainerID,Message,IsRead,CreatedOn) VALUES(@NotificationID,@TrainerID,@Message,0,GETDATE())",new SqlParameter[]{new SqlParameter("@NotificationID",id),new SqlParameter("@TrainerID",Sender),new SqlParameter("@Message",txtMessage.Text.Trim())});txtMessage.Text="";lblMessage.Text="Notification published successfully.";lblMessage.ForeColor=System.Drawing.Color.Green;BindGrid();}private void BindGrid(){DataTable d=obj.GetDataTable("SELECT NotificationID,Message,CreatedOn,CAST(1 AS bit) HasPdf FROM Notification WHERE TrainerID=@TrainerID ORDER BY CreatedOn DESC",new SqlParameter[]{new SqlParameter("@TrainerID",Sender)});gvNotifications.DataSource=d;gvNotifications.DataBind();}}}